#[test]
fn fortress_starts_match_java() {
    for l in FORTRESS.lines().filter(|l| !l.is_empty()) {
        let f: Vec<&str> = l.split_whitespace().collect();
        // Golden vectors come from vanilla java.util.Random (scrambled setSeed). The port models Hodgepodge's
        // unscrambled StdLCG, so vanilla(seed) == port(seed ^ 0x5DEECE66D).
        let seed: i64 = f[1].parse::<i64>().unwrap() ^ 0x5DEECE66D;
        let mut n = 0;
        let mut h: u64 = 0xcbf29ce484222325;
        let mut near = Vec::new();
        for cz in -256..256 {
            for cx in -256..256 {
                if is_fortress_chunk(seed, cx, cz) {
                    n += 1;
                    for v in [cx, cz] {
                        h ^= v as u32 as u64;
                        h = h.wrapping_mul(0x100000001b3);
                    }
                    if cx.abs() < 64 && cz.abs() < 64 {
                        near.push(format!("{cx},{cz}"));
                    }
                }
            }
        }
        assert_eq!(n.to_string(), f[2], "seed {seed}");
        assert_eq!(format!("{h:x}"), f[3], "seed {seed}");
        assert_eq!(near, f[4..].to_vec(), "seed {seed}");
        let list = fortresses_in(seed, -256, -256, 255, 255);
        assert_eq!(list.len(), n);
        // row-major chunk order like the census
        let mut sorted = list.clone();
        sorted.sort_by_key(|f| (f.chunk_z, f.chunk_x));
        let mut h2: u64 = 0xcbf29ce484222325;
        for f in &sorted {
            for v in [f.chunk_x, f.chunk_z] {
                h2 ^= v as u32 as u64;
                h2 = h2.wrapping_mul(0x100000001b3);
            }
        }
        assert_eq!(h2, h);
    }
}

fn fnv(v: &[i32]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &x in v {
        h ^= x as u32 as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}

#[test]
fn hell_biomes_match_java() {
    let mut n = 0;
    for l in HELL.lines().filter(|l| !l.is_empty()) {
        let f: Vec<&str> = l.split_whitespace().collect();
        let seed: i64 = f[1].parse().unwrap();
        let (x, z, w, h): (i32, i32, i32, i32) = (
            f[2].parse().unwrap(),
            f[3].parse().unwrap(),
            f[4].parse().unwrap(),
            f[5].parse().unwrap(),
        );
        let nb = NetherBiomes::new(seed);
        assert_eq!(format!("{:x}", fnv(&nb.biomes(x, z, w, h))), f[6], "{l}");
        assert_eq!(
            format!("{:x}", fnv(&nb.biomes_quarter(x >> 2, z >> 2, w, h))),
            f[8],
            "quarter {l}"
        );
        n += 1;
    }
    assert_eq!(n, 40);
    for l in HELL_BLOCKS.lines().filter(|l| !l.is_empty()) {
        let f: Vec<&str> = l.split_whitespace().collect();
        let seed: i64 = f[1].parse().unwrap();
        let (x, z, s): (i32, i32, i32) = (
            f[2].parse().unwrap(),
            f[3].parse().unwrap(),
            f[4].parse().unwrap(),
        );
        let want: Vec<i32> = f[5..].iter().map(|v| v.parse().unwrap()).collect();
        let nb = NetherBiomes::new(seed);
        assert_eq!(nb.biomes(x, z, s, s), want);
        for (i, &b) in want.iter().enumerate().step_by(37) {
            assert_eq!(nb.biome_at(x + i as i32 % s, z + i as i32 / s), b);
        }
    }
}

#[test]
fn hell_biome_distribution() {
    let nb = NetherBiomes::new(1337);
    let mut hist = std::collections::BTreeMap::new();
    for b in nb.biomes_quarter(-2048, -2048, 1024, 1024) {
        *hist.entry(b).or_insert(0) += 1;
    }
    assert!(
        !hist.contains_key(&94),
        "Polar Chasm is unreachable (nextLong(6) * 10 < 60)"
    );
    assert_eq!(hist.len(), 6);
    let t = std::time::Instant::now();
    let v = nb.biomes(0, 0, 512, 512);
    println!(
        "nether 1:4 histogram {hist:?}; {:.1} ns/block [{}]",
        t.elapsed().as_secs_f64() * 1e9 / (512.0 * 512.0),
        v[0]
    );
}

#[test]
fn gt_vein_candidates() {
    // Provisional lists: sanity (weights, heights) and determinism; exact vs the game needs the dump.
    let nether = vein_table(&GT_NETHER_VEINS);
    let tf = vein_table(&GT_TF_VEINS);
    assert_eq!(nether.overworld.iter().map(|v| v.weight).sum::<i32>(), 625);
    assert_eq!(tf.overworld.iter().map(|v| v.weight).sum::<i32>(), 1053);
    let mut hist = vec![0; nether.overworld.len()];
    for oz in -20..20 {
        for ox in -20..20 {
            let (ox, oz) = (ox * 3 + 1, oz * 3 + 1);
            let c = gt_candidates(1337, NETHER_DIM, &nether, &GT_GTNH, ox, oz, 2);
            assert_eq!(c.len(), 2);
            let p = c[0];
            let v = &nether.overworld[p.vein];
            assert!(p.min_y >= v.min_y && p.min_y < v.max_y - 5);
            assert!(p.west <= ox * 16 && p.east >= ox * 16 + 16);
            hist[p.vein] += 1;
            let t = gt_candidates(
                1337,
                rwg2_biomes::twilight::TF_DIM,
                &tf,
                &GT_GTNH,
                ox,
                oz,
                1,
            );
            let tv = &tf.overworld[t[0].vein];
            assert!(t[0].min_y >= tv.min_y && t[0].min_y < tv.max_y - 5);
        }
    }
    // dimension id is in the seed: dim -1 and dim 0 differ
    let a = gt_candidates(1337, NETHER_DIM, &nether, &GT_GTNH, 1, 1, 1)[0];
    let b = gt_candidates(1337, 0, &nether, &GT_GTNH, 1, 1, 1)[0];
    assert_ne!((a.vein, a.min_y, a.west), (b.vein, b.min_y, b.west));
    println!(
        "nether first-pick histogram (1600 oreseeds): {:?}",
        nether
            .overworld
            .iter()
            .map(|v| &v.name[8..])
            .zip(hist)
            .collect::<Vec<_>>()
    );
}
